import{_ as e,o as i,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"정기 기장 안내","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/12-scheduled-accounting-guide.md","filePath":"v1/ko/guide/12-scheduled-accounting-guide.md"}'),r={name:"v1/ko/guide/12-scheduled-accounting-guide.md"};function o(n,a,d,h,u,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="정기-기장-안내" tabindex="-1">정기 기장 안내 <a class="header-anchor" href="#정기-기장-안내" aria-label="Permalink to &quot;정기 기장 안내&quot;">​</a></h1><h2 id="_1-어떤-기능인가요" tabindex="-1">1. 어떤 기능인가요? <a class="header-anchor" href="#_1-어떤-기능인가요" aria-label="Permalink to &quot;1. 어떤 기능인가요?&quot;">​</a></h2><p>‘정기 기장’은 월세, 공과금, 구독 서비스, 급여처럼 일정하게 반복되는 수입/지출을 규칙으로 등록해, 규칙에 따라 자동으로 거래를 생성하는 기능입니다. 반복 입력을 줄일 수 있습니다.</p><h2 id="_2-이런-경우에-유용해요" tabindex="-1">2. 이런 경우에 유용해요 <a class="header-anchor" href="#_2-이런-경우에-유용해요" aria-label="Permalink to &quot;2. 이런 경우에 유용해요&quot;">​</a></h2><ul><li>매월 월세, 대출 상환, 카드 결제 대금</li><li>매주 통근 교통비, 고정 식비/수당</li><li>매월 구독 서비스(영상 멤버십, 클라우드 저장소 등)</li><li>매월 고정 수입(급여, 지원금 등)</li></ul><h2 id="_3-사용-방법" tabindex="-1">3. 사용 방법 <a class="header-anchor" href="#_3-사용-방법" aria-label="Permalink to &quot;3. 사용 방법&quot;">​</a></h2><ol><li><strong>설정</strong>에서 <strong>정기 기장</strong>을 찾습니다</li><li>새 규칙을 만들고 다음을 입력합니다: <ul><li>유형: 지출 / 수입</li><li>분류</li><li>금액</li><li>계정</li><li>태그, 메모(선택)</li><li>실행 주기: 매일 / 매주 / 매월(규칙에 따라 날짜 또는 요일 선택)</li><li>시작/종료: 시작일은 필수, 종료일은 선택(만료 시 자동 중지)</li></ul></li><li>저장하면 규칙이 정기 기장 목록에 표시됩니다</li><li>실행 시간이 되면 규칙에 따라 거래가 생성됩니다</li></ol><h2 id="_4-규칙-및-주의사항" tabindex="-1">4. 규칙 및 주의사항 <a class="header-anchor" href="#_4-규칙-및-주의사항" aria-label="Permalink to &quot;4. 규칙 및 주의사항&quot;">​</a></h2><ul><li>정기 기장으로 생성된 거래는 일반 수동 거래와 동일하게 목록에 표시되며 통계에 포함됩니다.</li><li>앱을 오래 열지 않으면 일부 기기에서는 ‘정확히 지정 시각’에 생성되지 않을 수 있습니다. 이 경우에도 다음에 앱을 열 때, 생성되어야 했지만 아직 생성되지 않은 거래를 자동으로 보완 생성합니다(누락 방지).</li><li>월세 인상, 계정 변경 등 상황이 바뀔 수 있으므로 규칙 목록을 주기적으로 점검하는 것을 권장합니다.</li><li>규칙을 일시정지/종료하면 더 이상 생성되지 않으며, 다시 활성화하면 다음 주기부터 실행됩니다.</li></ul><h2 id="_5-자주-묻는-질문" tabindex="-1">5. 자주 묻는 질문 <a class="header-anchor" href="#_5-자주-묻는-질문" aria-label="Permalink to &quot;5. 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-정기-기장으로-생성된-거래가-잘못되면-어떻게-하나요" tabindex="-1">Q1. 정기 기장으로 생성된 거래가 잘못되면 어떻게 하나요? <a class="header-anchor" href="#q1-정기-기장으로-생성된-거래가-잘못되면-어떻게-하나요" aria-label="Permalink to &quot;Q1. 정기 기장으로 생성된 거래가 잘못되면 어떻게 하나요?&quot;">​</a></h3><p>정기 기장으로 생성된 거래도 일반 거래처럼 수정하거나 삭제할 수 있습니다. 자주 발생한다면 해당 규칙(금액/주기/계정 등)을 조정하세요.</p><h3 id="q2-규칙을-수정하면-이미-생성된-거래도-자동으로-바뀌나요" tabindex="-1">Q2. 규칙을 수정하면 이미 생성된 거래도 자동으로 바뀌나요? <a class="header-anchor" href="#q2-규칙을-수정하면-이미-생성된-거래도-자동으로-바뀌나요" aria-label="Permalink to &quot;Q2. 규칙을 수정하면 이미 생성된 거래도 자동으로 바뀌나요?&quot;">​</a></h3><p>아니요. 규칙 변경은 이후에 생성되는 거래에만 적용되며, 과거 거래는 추적을 위해 그대로 유지됩니다.</p><h3 id="q3-같은-날에-여러-건이-생성될-수-있나요" tabindex="-1">Q3. 같은 날에 여러 건이 생성될 수 있나요? <a class="header-anchor" href="#q3-같은-날에-여러-건이-생성될-수-있나요" aria-label="Permalink to &quot;Q3. 같은 날에 여러 건이 생성될 수 있나요?&quot;">​</a></h3><p>여러 규칙을 설정했다면 규칙별로 거래가 각각 생성됩니다. 동일한 규칙에 대해서는 중복 생성이 되지 않도록 최대한 방지합니다.</p>',16)])])}const q=e(r,[["render",o]]);export{_ as __pageData,q as default};
